import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"订阅与计费","description":"","frontmatter":{},"headers":[],"relativePath":"admin/subscriptions.md","filePath":"admin/subscriptions.md","lastUpdated":1782304957000}'),e={name:"admin/subscriptions.md"};function i(o,t,s,n,h,c){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="订阅与计费" tabindex="-1">订阅与计费 <a class="header-anchor" href="#订阅与计费" aria-label="Permalink to &quot;订阅与计费&quot;">​</a></h1><blockquote><p>管理订阅套餐、卡密、用户订阅、计费配置。</p></blockquote><h2 id="订阅套餐-plan" tabindex="-1">订阅套餐（Plan） <a class="header-anchor" href="#订阅套餐-plan" aria-label="Permalink to &quot;订阅套餐（Plan）&quot;">​</a></h2><p>定义可供用户购买的套餐规格：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>计费模式</td><td>月付 / 年付 / 永久 / 自定义</td></tr><tr><td>价格</td><td>套餐价格</td></tr><tr><td>机器人配额</td><td>可创建的机器人数量</td></tr><tr><td>插件配额</td><td>可安装的插件数量</td></tr><tr><td>包含插件</td><td>套餐内含哪些插件（白名单或全部）</td></tr><tr><td>适配器权限</td><td>套餐可用哪些平台适配器</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">配额自动管控</p><p>用户的订阅决定其资源配额。订阅过期后资源自动降级（机器人停用、插件停用，但<strong>不删数据</strong>），续费即恢复。</p></div><h2 id="卡密系统" tabindex="-1">卡密系统 <a class="header-anchor" href="#卡密系统" aria-label="Permalink to &quot;卡密系统&quot;">​</a></h2><p>生成可兑换的卡密，分三类：</p><table tabindex="0"><thead><tr><th>卡密类型</th><th>兑换内容</th></tr></thead><tbody><tr><td><strong>套餐卡</strong></td><td>兑换一个订阅套餐</td></tr><tr><td><strong>余额卡</strong></td><td>充值到账户余额</td></tr><tr><td><strong>插件卡</strong></td><td>兑换某个付费插件</td></tr></tbody></table><p>操作：</p><ul><li><strong>批量生成</strong>：一次性生成多张卡密。</li><li><strong>导出</strong>：导出卡密列表分发给渠道。</li><li><strong>作废</strong>：失效未使用的卡密。</li><li><strong>使用记录</strong>：查看每张卡密被谁兑换。</li></ul><h2 id="订阅用户" tabindex="-1">订阅用户 <a class="header-anchor" href="#订阅用户" aria-label="Permalink to &quot;订阅用户&quot;">​</a></h2><p>查看所有用户的订阅状态：</p><ul><li>当前订阅套餐、到期时间。</li><li>续费记录。</li><li>手动延期 / 调整套餐（用于处理客诉、赠送）。</li></ul><h2 id="支付配置" tabindex="-1">支付配置 <a class="header-anchor" href="#支付配置" aria-label="Permalink to &quot;支付配置&quot;">​</a></h2><p>支付集成在 <a href="./settings">系统设置</a> 里配置：</p><ul><li>彩虹易支付接口（V1 / V2 协议）。</li><li>商户号、密钥等。</li><li>充值档位设置。</li></ul><div class="warning custom-block"><p class="custom-block-title">支付配置要保密</p><p>支付密钥属于敏感信息，配置后注意权限控制，不要泄露。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>用户视角的订阅 → <a href="./../console/subscriptions">用户控制台 · 我的订阅</a></li><li>支付怎么配 → <a href="./settings">系统设置</a></li></ul>',20)])])}const b=a(e,[["render",i]]);export{u as __pageData,b as default};
